import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { cv } from '@/data/personal';
import { renderCvPreview } from '@/lib/cvPreview';

// Rendered once, while the site builds, from the PDF in public/ — so the
// preview is always of the CV that deploys alongside it, and nothing has to be
// regenerated by hand when the PDF changes.
export const dynamic = 'force-static';

export async function GET(): Promise<Response> {
  const png = await renderCvPreview(await readFile(path.join(process.cwd(), 'public', cv.file)));
  return new Response(new Uint8Array(png), { headers: { 'content-type': 'image/png' } });
}
